-- ROLLBACK-ONLY REVIEW. Automatic game runway and airport restriction screening.
-- This is not flight clearance. No approval rows are generated by this file.
BEGIN;
CREATE TABLE airlinerra_game.aircraft_storage_only_airport_rules_v1(
 world_id smallint NOT NULL CHECK(world_id=1), airport_key text NOT NULL,
 -- Reviewed game performance adjustment; never silently assume sea-level performance.
 runway_elevation_factor numeric NOT NULL CHECK(runway_elevation_factor>=1),
 minimum_usable_runway_width_m numeric NOT NULL CHECK(minimum_usable_runway_width_m>0),
 nighttime_ban boolean NOT NULL,
 curfew_start_local time,curfew_end_local time,
 noise_restrictions boolean NOT NULL,permitted_noise_chapters smallint[],
 rule_reference text NOT NULL CHECK(btrim(rule_reference)<>''),
 reviewed_at timestamptz NOT NULL,
 PRIMARY KEY(world_id,airport_key),
 FOREIGN KEY(world_id,airport_key) REFERENCES airlinerra_game.aircraft_storage_airport_operational_profiles_v1(world_id,airport_key),
 CHECK((nighttime_ban AND curfew_start_local IS NOT NULL AND curfew_end_local IS NOT NULL AND curfew_start_local<>curfew_end_local)
 OR (NOT nighttime_ban AND curfew_start_local IS NULL AND curfew_end_local IS NULL)),
 CHECK((noise_restrictions AND permitted_noise_chapters IS NOT NULL AND cardinality(permitted_noise_chapters)>0 AND array_position(permitted_noise_chapters,NULL) IS NULL)
 OR (NOT noise_restrictions AND permitted_noise_chapters IS NULL))
);
ALTER TABLE airlinerra_game.aircraft_storage_only_airport_rules_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON airlinerra_game.aircraft_storage_only_airport_rules_v1 FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION airlinerra_game.aircraft_storage_leg_airport_screen_v1(p_airport text,p_configuration bigint,p_operation text,p_at timestamptz,p_storage_endpoint boolean)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $fn$
DECLARE f airlinerra_game.aircraft_storage_facilities_v1%ROWTYPE;p record;r record;v record;cert record;required_m numeric;local_time time;curfew_block boolean:=false;noise_block boolean:=false;simple jsonb;universal jsonb;screen record;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION USING ERRCODE='42501';END IF;
 IF p_airport IS NULL OR p_configuration IS NULL OR p_operation IS NULL OR p_operation NOT IN('departure','arrival') OR p_at IS NULL OR p_storage_endpoint IS NULL THEN RETURN jsonb_build_object('passed',false,'status','invalid_airport_screen');END IF;
 IF p_storage_endpoint THEN
  SELECT * INTO f FROM airlinerra_game.aircraft_storage_facilities_v1 WHERE world_id=1 AND airport_key=p_airport;
  IF NOT FOUND OR airlinerra_game.aircraft_storage_airport_admission_v1(p_airport,CASE WHEN p_operation='departure' THEN 'storage_reactivation' ELSE 'storage_inbound' END)->>'eligible' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('passed',false,'status','storage_airport_not_approved');END IF;
 END IF;
 IF NOT p_storage_endpoint OR f.admission_scope='existing_commercial' THEN
  IF NOT EXISTS(SELECT 1 FROM airlinerra_game.airport_unified_operations_v1 WHERE world_id=1 AND airport_key=p_airport AND operationally_authorized AND dispatch_eligible_by_airport_admission) THEN RETURN jsonb_build_object('passed',false,'status','commercial_airport_not_authorized');END IF;
  SELECT * INTO screen FROM airlinerra_game.section5_full_weight_airport_aircraft_screen_v2 WHERE world_id=1 AND airport_key=p_airport AND configuration_id=p_configuration;
  IF NOT FOUND OR screen.high_elevation_needs_site_specific_review IS DISTINCT FROM false OR (CASE WHEN p_operation='departure' THEN screen.full_weight_takeoff_length_pass ELSE screen.full_weight_landing_length_pass END) IS DISTINCT FROM true THEN RETURN jsonb_build_object('passed',false,'status','commercial_runway_screen_blocked');END IF;
  simple:=airlinerra_game.section5_simplified_airport_leg_screen_v1(1::smallint,p_airport,p_configuration,p_operation,p_at);
  universal:=airlinerra_game.section5_universal_airport_leg_restriction_v1(1::smallint,p_airport,p_configuration,p_operation,p_at,NULL::text);
  IF simple->>'gameHardBlocked' IS DISTINCT FROM 'false' OR simple->>'needsReview' IS DISTINCT FROM 'false' OR universal->>'gameHardBlocked' IS DISTINCT FROM 'false' OR universal->>'needsReview' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('passed',false,'status','commercial_restriction_blocked_or_unverified','simplified',simple,'universal',universal);END IF;
  RETURN jsonb_build_object('passed',true,'status','commercial_game_airport_screen_pass','runwayReference',screen.runway_reference_source_id,'formulaVersion',screen.formula_version,'simplified',simple,'universal',universal,'dispatchAuthorized',false);
 END IF;
 IF f.admission_scope IS DISTINCT FROM 'relocation_only' THEN RETURN jsonb_build_object('passed',false,'status','storage_scope_invalid');END IF;
 SELECT * INTO p FROM airlinerra_game.aircraft_storage_airport_operational_profiles_v1 WHERE world_id=1 AND airport_key=p_airport;
 SELECT * INTO r FROM airlinerra_game.aircraft_storage_only_airport_rules_v1 WHERE world_id=1 AND airport_key=p_airport;
 IF NOT FOUND OR airlinerra_game.section9_verified_world_instant_v1() IS NULL OR r.reviewed_at>airlinerra_game.section9_verified_world_instant_v1() OR p.reviewed_at>airlinerra_game.section9_verified_world_instant_v1() THEN RETURN jsonb_build_object('passed',false,'status','storage_operational_rules_missing');END IF;
 SELECT * INTO v FROM airlinerra_game.section5_full_weight_aircraft_reference_v2 WHERE configuration_id=p_configuration;
 IF NOT FOUND THEN RETURN jsonb_build_object('passed',false,'status','aircraft_runway_reference_missing');END IF;
 required_m:=ceil((CASE WHEN p_operation='departure' THEN v.game_full_weight_takeoff_reference_m ELSE v.game_full_weight_landing_reference_m END)*r.runway_elevation_factor);
 IF required_m IS NULL OR required_m<=0 OR upper(p.runway_surface) NOT IN('ASP','ASPHALT','CON','CONCRETE','ASPHALT/CONCRETE','CONCRETE/ASPHALT','BITUMEN') OR p.runway_length_m<required_m OR p.runway_width_m<r.minimum_usable_runway_width_m THEN RETURN jsonb_build_object('passed',false,'status','storage_runway_screen_blocked','requiredRunwayM',required_m,'availableRunwayM',p.runway_length_m);END IF;
 local_time:=(p_at AT TIME ZONE p.timezone_iana)::time;
 IF r.nighttime_ban THEN
 curfew_block:=CASE WHEN r.curfew_start_local<=r.curfew_end_local THEN local_time BETWEEN r.curfew_start_local AND r.curfew_end_local ELSE local_time>=r.curfew_start_local OR local_time<=r.curfew_end_local END;
 END IF;
 IF curfew_block THEN RETURN jsonb_build_object('passed',false,'status','storage_curfew_blocked','localTime',local_time);END IF;
 IF r.noise_restrictions THEN
 SELECT * INTO cert FROM airlinerra_game.section5_icao_aircraft_certification_v2 WHERE configuration_id=p_configuration;
 IF NOT FOUND OR cert.noise_certificate_status IS DISTINCT FROM 'CERTIFICATE_CONFIGURATION_MATCHED' OR cert.official_icao_chapter IS NULL THEN RETURN jsonb_build_object('passed',false,'status','storage_noise_certificate_unverified');END IF;
 noise_block:=NOT (cert.official_icao_chapter=ANY(r.permitted_noise_chapters) OR (cert.official_icao_chapter=14 AND 4=ANY(r.permitted_noise_chapters)));
 IF noise_block THEN RETURN jsonb_build_object('passed',false,'status','storage_noise_chapter_blocked');END IF;
 END IF;
 RETURN jsonb_build_object('passed',true,'status','storage_game_airport_screen_pass','requiredRunwayM',required_m,'availableRunwayM',p.runway_length_m,'runwayReference',p.runway_evidence_reference,'restrictionReference',r.rule_reference,'formulaVersion',v.game_formula_version,'dispatchAuthorized',false);
END $fn$;
REVOKE ALL ON FUNCTION airlinerra_game.aircraft_storage_leg_airport_screen_v1(text,bigint,text,timestamptz,boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION airlinerra_game.owned_aircraft_storage_operational_screen_v1(p_player uuid,p_airline uuid,p_aircraft uuid,p_purpose text,p_destination text,p_departure timestamptz)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $fn$
DECLARE q jsonb;ctx jsonb;outbound boolean;cfg bigint;origin text;arrival timestamptz;o jsonb;d jsonb;licence jsonb;maintenance jsonb;game_day date;coverage_days int;
BEGIN
 q:=airlinerra_game.owned_aircraft_storage_cost_preview_v1(p_player,p_airline,p_aircraft,p_purpose,p_destination,p_departure);
 IF q->>'status' IS DISTINCT FROM 'storage_cost_preview_verified' THEN RETURN q||jsonb_build_object('airportScreenPassed',false,'clearanceGenerated',false);END IF;
 ctx:=airlinerra_game.owned_aircraft_storage_planning_context_v1(p_player,p_airline,p_aircraft,p_purpose);
 cfg:=(ctx->>'configurationId')::bigint;origin:=q->>'originAirportKey';arrival:=(q->>'arrivalUtc')::timestamptz;outbound:=p_purpose='storage_reactivation';
 o:=airlinerra_game.aircraft_storage_leg_airport_screen_v1(origin,cfg,'departure',p_departure,outbound);
 d:=airlinerra_game.aircraft_storage_leg_airport_screen_v1(p_destination,cfg,'arrival',arrival,NOT outbound);
 licence:=airlinerra_game.aircraft_storage_ferry_licence_screen_v1(p_airline,p_purpose,origin,p_destination,p_departure,arrival);
 RETURN q||jsonb_build_object('airportScreenPassed',o->>'passed'='true' AND d->>'passed'='true','departureScreen',o,'arrivalScreen',d,'licenceScreen',licence,'crewScreen',airlinerra_game.aircraft_storage_crew_requirements_v1(cfg,origin,p_destination,p_departure,arrival),'clearanceGenerated',false,'bookingEligible',false,'dispatchAuthorized',false);
END $fn$;
REVOKE ALL ON FUNCTION airlinerra_game.owned_aircraft_storage_operational_screen_v1(uuid,uuid,uuid,text,text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
ROLLBACK;
